PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS place;

CREATE TABLE place(
  zip CHAR(5),
  city VARCHAR(100),
  state CHAR(2),
  city_phone VARCHAR(5),
  lat NUMERIC(9,6),
  lon NUMERIC(9,6),
  status CHAR(1),
  fips_class CHAR(2),
  fips_place CHAR(7),
  fips_county CHAR(5),
  priority char(1));
COMMIT;
